\NeedsTeXFormat{LaTeX2e}
\ProvidesPackage{handy-macros}[2026/10/07 v1.0 Handy math shorthand macros]

% In-house utility package (not a CTAN mirror). Provides a small set of
% commonly used math shorthand macros written from first principles.

\RequirePackage{amsmath}
\RequirePackage{amssymb}

% Common number sets.
\newcommand{\RR}{\mathbb{R}}
\newcommand{\NN}{\mathbb{N}}
\newcommand{\ZZ}{\mathbb{Z}}
\newcommand{\QQ}{\mathbb{Q}}
\newcommand{\CC}{\mathbb{C}}

% Upright differential operator, e.g. \int f(x) \, \dd x
\newcommand{\dd}{\mathrm{d}}

% Absolute value and norm with auto-sized delimiters.
\newcommand{\abs}[1]{\left\lvert #1 \right\rvert}
\newcommand{\norm}[1]{\left\lVert #1 \right\rVert}

% Set-builder notation, e.g. \set{x \in \RR : x > 0}
\newcommand{\set}[1]{\left\{ #1 \right\}}

% Bold vector shorthand.
\newcommand{\vect}[1]{\boldsymbol{#1}}

% Partial derivative, e.g. \pd{f}{x}
\newcommand{\pd}[2]{\frac{\partial #1}{\partial #2}}

\endinput

\NeedsTeXFormat{LaTeX2e}
\ProvidesPackage{code-listing-style}[2026/10/07 v1.0 Preset code listing style]

% In-house utility package (not a CTAN mirror). Wraps the standard
% "listings" package with a single ready-to-use style preset.

\RequirePackage{listings}
\RequirePackage{xcolor}

\definecolor{codebg}{RGB}{245,245,245}
\definecolor{codekeyword}{RGB}{0,0,160}
\definecolor{codecomment}{RGB}{90,120,90}
\definecolor{codestring}{RGB}{160,30,30}

\lstdefinestyle{handystyle}{
  backgroundcolor=\color{codebg},
  basicstyle=\ttfamily\small,
  keywordstyle=\color{codekeyword}\bfseries,
  commentstyle=\color{codecomment}\itshape,
  stringstyle=\color{codestring},
  numbers=left,
  numberstyle=\tiny\color{gray},
  numbersep=8pt,
  frame=single,
  breaklines=true,
  showstringspaces=false,
  tabsize=2,
  captionpos=b,
}

\lstset{style=handystyle}

\endinput

\NeedsTeXFormat{LaTeX2e}
\ProvidesPackage{simple-titlepage}[2026/10/07 v1.0 Minimal custom title page]

% In-house utility package (not a CTAN mirror). Defines one command,
% \simpletitlepage{title}{author}{date}, that typesets a clean title
% page using only the "titlepage" environment already provided by the
% standard article/report/book classes.

\newcommand{\simpletitlepage}[3]{%
  \begin{titlepage}
    \centering
    \vspace*{3cm}
    {\Huge\bfseries #1\par}
    \vspace{1.5cm}
    {\Large #2\par}
    \vspace{1cm}
    {\large #3\par}
    \vfill
    \hrule height 0.5pt
    \vspace{0.3cm}
    {\small Prepared with the simple-titlepage package\par}
  \end{titlepage}
}

\endinput

\NeedsTeXFormat{LaTeX2e}
\ProvidesPackage{quick-tables}[2026/10/07 v1.0 Booktabs-based table helpers]

% In-house utility package (not a CTAN mirror). Adds a bold-header
% shorthand and a fixed-width centered column type on top of the
% standard "booktabs" and "array" packages.

\RequirePackage{booktabs}
\RequirePackage{array}

% Bold header cell shorthand, e.g. \head{Name}
\newcommand{\head}[1]{\textbf{#1}}

% Centered, fixed-width column type, e.g. C{3cm}
\newcolumntype{C}[1]{>{\centering\arraybackslash}p{#1}}

\endinput

